            locZone: 'אזור',
            locEstimate: (n, m) => n + ' פריטים, כ־' + m + ' MB להורדה',
            locDownload: 'הורדה',
            locStop: 'עצירה',
            locProgress: (a, b, p) => a + ' / ' + b + ' — ' + p + ' %',
            locDone: (n) => 'הורד: ' + n + '. קווי המתאר מקומיים כעת.',
            locStopped: 'ההורדה נעצרה; מה שהגיע נשאר מקומי.',
            locVolume: (n, mo) => n + ' בקשות, ' + mo + ' MB התקבלו',
            locStored: (n) => n + ' פריטים מקומיים למדינה זו.',
            locNone: 'עדיין אין נתונים מקומיים למדינה זו.',
            locClear: 'מחיקת הנתונים המקומיים של מדינה זו',
            locClearConfirm: 'אישור המחיקה',
            locAuto: 'במדינה זו, כל קו מתאר שהורד נשמר מקומית אוטומטית, מהפעלה להפעלה.',
            locEmbedded: 'הנתונים של מדינה זו משולבים בסקריפט: אין מה להוריד.',
            locFromStock: '(מקומי)',
