                SRSNAME: 'EPSG:4326',
                TYPENAMES: (precise ? 'ADMINEXPRESS-COG-CARTO.LATEST:' : 'ADMINEXPRESS-COG-CARTO-PE.LATEST:') + n.couche,
                PROPERTYNAME: 'nom_officiel,' + n.code + (n.dep ? ',' + n.dep : '') + ',geometrie',
