            generique: true,
            tolTout: 0.001,    // ~100 m : niveaux chargés en entier (régions, provinces), pour l'affichage et la couverture
            tolVue: 0.0001,    // ~10 m : niveaux fins, par tuiles (invisible à l'écran ; le stock les garde à ~5 m)
