    // ---------- Shapefile : un enregistrement Polygon (type 5), en WGS84 ----------
    // Le format veut les anneaux EXTÉRIEURS dans le sens horaire et les trous dans le sens inverse ;
    // GeoJSON (RFC 7946) fait l'inverse : on retourne ce qui doit l'être.
    const aireSignee = r => { let a = 0; for (let i = 1; i < r.length; i++) a += (r[i][0] - r[i - 1][0]) * (r[i][1] + r[i - 1][1]); return a; };
    const sens = (r, horaire) => (aireSignee(r) > 0) === horaire ? r : r.slice().reverse();
    function shapefile(z) {
        const anneaux = [];
        for (const p of polysDe(z.geom)) p.forEach((r, i) => anneaux.push(sens(r, i === 0)));
        const pts = anneaux.reduce((n, r) => n + r.length, 0);
        const bb = emprise(z.geom);
        const contenu = 44 + 4 * anneaux.length + 16 * pts;                 // octets du contenu de l'enregistrement
        const entete = (dv, longueurOctets) => {
            dv.setInt32(0, 9994, false); dv.setInt32(24, longueurOctets / 2, false);
            dv.setInt32(28, 1000, true); dv.setInt32(32, 5, true);
            bb.forEach((v, i) => dv.setFloat64(36 + 8 * i, v, true));
        };
        const shp = new ArrayBuffer(100 + 8 + contenu), d = new DataView(shp);
        entete(d, shp.byteLength);
        d.setInt32(100, 1, false); d.setInt32(104, contenu / 2, false);
        let o = 108;
        d.setInt32(o, 5, true); bb.forEach((v, i) => d.setFloat64(o + 4 + 8 * i, v, true));
        d.setInt32(o + 36, anneaux.length, true); d.setInt32(o + 40, pts, true);
        o += 44;
        let k = 0;
        for (const r of anneaux) { d.setInt32(o, k, true); o += 4; k += r.length; }
        for (const r of anneaux) for (const [x, y] of r) { d.setFloat64(o, x, true); d.setFloat64(o + 8, y, true); o += 16; }
        const shx = new ArrayBuffer(108), dx = new DataView(shx);
        entete(dx, 108); dx.setInt32(100, 50, false); dx.setInt32(104, contenu / 2, false);
        // dBase III : deux champs texte, NAME et SOURCE, en UTF-8 (déclaré par le .cpg).
        const enc = s => new TextEncoder().encode(String(s));
        const champs = [['NAME', 254, z.nom], ['SOURCE', 254, z.source + ' - ' + z.licence]];
        const lgEnreg = 1 + champs.reduce((n, c) => n + c[1], 0), lgEntete = 32 + 32 * champs.length + 1;
        const dbf = new Uint8Array(lgEntete + lgEnreg + 1), db = new DataView(dbf.buffer), j = new Date();
        dbf[0] = 3; dbf[1] = j.getFullYear() - 1900; dbf[2] = j.getMonth() + 1; dbf[3] = j.getDate();
        db.setUint32(4, 1, true); db.setUint16(8, lgEntete, true); db.setUint16(10, lgEnreg, true);
        champs.forEach(([nom, lg], i) => { dbf.set(enc(nom), 32 + 32 * i); dbf[32 + 32 * i + 11] = 0x43; dbf[32 + 32 * i + 16] = lg; });
        dbf[lgEntete - 1] = 0x0d;
        let p = lgEntete; dbf[p++] = 0x20;
        for (const [, lg, val] of champs) { const b = enc(val).slice(0, lg); dbf.fill(0x20, p, p + lg); dbf.set(b, p); p += lg; }
        dbf[p] = 0x1a;
        const prj = 'GEOGCS["GCS_WGS_1984",DATUM["D_WGS_1984",SPHEROID["WGS_1984",6378137.0,298.257223563]],PRIMEM["Greenwich",0.0],UNIT["Degree",0.0174532925199433]]';
        const base = slug(z.nom);
        return [[base + '.shp', new Uint8Array(shp)], [base + '.shx', new Uint8Array(shx)], [base + '.dbf', dbf], [base + '.prj', enc(prj)], [base + '.cpg', enc('UTF-8')]];
    }
