        // découpage (gris), ni avec la zone composée (bleu), ni avec la sélection (orange).
        await sdk.Map.addLayer({
            layerName: L_GEST,
            styleContext: {
                lbl: ({ feature }) => (feature && feature.properties && feature.properties.lbl) || '',
                op: ({ feature }) => (feature && feature.properties && feature.properties.op) || 0.18,
                col: ({ feature }) => (feature && feature.properties && feature.properties.col) || '#6a1b9a',
                w: ({ feature }) => (feature && feature.properties && feature.properties.w) || 2.5,
                so: ({ feature }) => (feature && feature.properties && feature.properties.so) || 1,
            },
            styleRules: [{ style: { fillColor: '${col}', fillOpacity: '${op}', strokeColor: '${col}', strokeWidth: '${w}', strokeOpacity: '${so}',
                label: '${lbl}', fontColor: '#ffffff', fontSize: '12px', fontWeight: 'bold', labelOutlineColor: '#4a148c', labelOutlineWidth: 3, pointerEvents: 'none' } }],
        });
        // La zone choisie dans une fiche : jaune vif, trait épais — elle doit sauter aux yeux au-dessus de tout.
        await sdk.Map.addLayer({
            layerName: L_FOCUS,
            styleContext: { lbl: ({ feature }) => (feature && feature.properties && feature.properties.lbl) || '' },
            styleRules: [{ style: { fillColor: '#ffeb3b', fillOpacity: 0.28, strokeColor: '#fdd835', strokeWidth: 5, strokeOpacity: 1, pointerEvents: 'none',
                label: '${lbl}', fontColor: '#5d4037', fontSize: '13px', fontWeight: 'bold', labelOutlineColor: '#fff59d', labelOutlineWidth: 4 } }],
        });
        for (const n of [L_ENT, L_SEL, L_RES, L_GEST, L_FOCUS]) { try { pw.W.map.setLayerIndex(pw.W.map.getLayersByName(n)[0], 9999); } catch (e) { } }
